INSERT INTO "Tbl_PlantillaCorreo" ("id", "Plantilla", "EsHtml", "Asunto", "idUsuarioInterno", "fechaRegistro", "activo")
SELECT
    1,
        '<!DOCTYPE html><html lang="es"><head> <meta charset="UTF-8" /> <meta name="viewport" content="width=device-width, initial-scale=1.0" /> <title>Contraseña Temporal</title> <style> * { margin: 0; padding: 0; box-sizing: border-box; } body { background-color: #f0f4f8; font-family: "Segoe UI", Arial, sans-serif; -webkit-text-size-adjust: 100%; } .wrapper { width: 100%; padding: 40px 16px; background-color: #f0f4f8; } .card { max-width: 560px; margin: 0 auto; background-color: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08); } .header { background: linear-gradient(135deg, #003087 0%, #0057b8 100%); padding: 36px 40px; text-align: center; } .header-logo { font-size: 26px; font-weight: 700; color: #ffffff; letter-spacing: 2px; text-transform: uppercase; } .header-logo span { color: #7eb8f7; } .header-subtitle { margin-top: 6px; font-size: 12px; color: #a8c8f0; letter-spacing: 1px; text-transform: uppercase; } .body { padding: 40px 40px 32px; } .greeting { font-size: 20px; font-weight: 600; color: #1a2e4a; margin-bottom: 16px; } .text { font-size: 15px; color: #4a5568; line-height: 1.7; margin-bottom: 16px; } .password-box { margin: 28px 0; background-color: #f7faff; border: 2px dashed #0057b8; border-radius: 10px; padding: 24px; text-align: center; } .password-value { font-size: 28px; font-weight: 700; color: #003087; letter-spacing: 6px; font-family: "Courier New", monospace; text-align: center; } .warning-box { background-color: #fff8e6; border-left: 4px solid #f5a623; border-radius: 0 8px 8px 0; padding: 14px 18px; margin-bottom: 24px; } .warning-box p { font-size: 13px; color: #7a5800; line-height: 1.6; } .warning-box strong { color: #5a4000; } .steps-title { font-size: 13px; font-weight: 600; color: #1a2e4a; margin-bottom: 12px; text-transform: uppercase; letter-spacing: 0.5px; } .steps { list-style: decimal; list-style-position: inside; margin-bottom: 28px; padding-left: 4px; } .steps li { font-size: 14px; color: #4a5568; line-height: 1.5; margin-bottom: 10px; } .divider { border: none; border-top: 1px solid #e8edf3; margin: 0 0 24px; } .help-text { font-size: 13px; color: #718096; line-height: 1.6; } .help-text a { color: #0057b8; text-decoration: none; } .footer { background-color: #f7f9fc; border-top: 1px solid #e8edf3; padding: 24px 40px; text-align: center; } .footer p { font-size: 12px; color: #a0aec0; line-height: 1.7; } .footer strong { color: #718096; } @media (max-width: 480px) { .header { padding: 28px 24px; } .body { padding: 28px 24px 24px; } .footer { padding: 20px 24px; } .password-value { font-size: 22px; letter-spacing: 4px; } } </style></head><body> <div class="wrapper"> <div class="card"> <div class="header"> <div class="header-logo">JAP<span>DEVA</span></div> <div class="header-subtitle">Sistema de Gestión Institucional</div> </div> <div class="body"> <p class="greeting">Hola, {{NOMBRE}}</p> <p class="text">Recibimos una solicitud para restablecer la contraseña asociada a tu cuenta. A continuación, encontrarás tu <strong>contraseña temporal</strong>:</p> <div class="password-box"> <p class="password-value">{{CONTRASENA_TEMPORAL}}</p> </div> <div class="warning-box"> <p><strong>Importante:</strong> Esta contraseña es válida por <strong>24 horas</strong>. Por seguridad, te recomendamos cambiarla inmediatamente después de iniciar sesión.</p> </div> <p class="steps-title">¿Cómo continuar?</p> <ol class="steps"> <li>Ingresa a la aplicación con tu correo y la contraseña temporal.</li> <li>Dirígete a <strong>Mi Perfil → Cambiar contraseña</strong>.</li> <li>Establece una nueva contraseña segura.</li> </ol> <hr class="divider" /> <p class="help-text">Si no solicitaste este cambio, puedes ignorar este correo. Tu contraseña actual permanecerá sin cambios. Si tienes dudas, contacta al soporte técnico en <a href="mailto:soporte@japdeva.go.cr">soporte@japdeva.go.cr</a>.</p> </div> <div class="footer"> <p><strong>JAPDEVA</strong> · Junta de Administración Portuaria y de Desarrollo Económico de la Vertiente Atlántica<br />Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br />&copy; {{ANIO}} JAPDEVA. Todos los derechos reservados.</p> </div> </div> </div></body></html>',
        TRUE,
        'Recuperación de contraseña',
        1,
        NOW(),
        TRUE
WHERE NOT EXISTS (SELECT 1 FROM "Tbl_PlantillaCorreo" WHERE "id" = 1);
